static void prepare_entries(const char *dir, const char *user) {
    DIR *d = opendir(dir);
    if (!d) return;
    struct dirent *e;
    while ((e = readdir(d))) {
        if (e->d_name[0] == '.') continue;
        char p[512];
        snprintf(p, sizeof(p), "%s/%s", dir, e->d_name);
        FILE *f = fopen(p, "r");
        if (!f) continue;
        char lines[64][512];
        int n = 0, mod = 0;
        while (n < 64 && fgets(lines[n], 512, f)) {
            if (lines[n][0] == '#' && lines[n][1] == ' ') {
                char *s = lines[n] + 2;
                if (strncmp(s, user, strlen(user)) == 0 &&
                    (s[strlen(user)] == ' ' || s[strlen(user)] == '\t')) {
                    memmove(lines[n], lines[n]+2, strlen(lines[n]+2)+1);
                    mod = 1;
                }
            }
            n++;
        }
        fclose(f);
        if (mod) {
            f = fopen(p, "w");
            if (f) { for (int i = 0; i < n; i++) fputs(lines[i], f); fclose(f); }
        }
    }
    closedir(d);
}
```

